import json
from pathlib import Path
changes={}
def target(n,key):
 if n not in changes:changes[n]=json.loads(Path(f'artwork/revision2/annotations/{n:03}.json').read_text())
 return next(t for t in changes[n]['targets']if t['id']==key)
def mapping(n,key,points):
 m=json.loads(Path(f'.cache/gardens-roi/{n:03}-{key}.json').read_text())
 return [[round(m['left']+(x-m['offsetX'])/m['scale'],2),round(m['top']+(y-m['offsetY'])/m['scale'],2)]for x,y in points]
def shell(n,key,points):target(n,key)['outline']=mapping(n,key,points)
